import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../app/app.dart';import '../../../core/providers.dart';
class SettingsScreen extends ConsumerWidget {const SettingsScreen({super.key});@override Widget build(context,ref)=>Scaffold(appBar:AppBar(title:const Text('Settings')),body:ListView(children:[for(final x in const [(Icons.person_outline,'Account'),(Icons.family_restroom,'Family'),(Icons.group_outlined,'Family members'),(Icons.child_care,'Babies'),(Icons.straighten,'Units · ml, kg, cm'),(Icons.info_outline,'About')]) ListTile(leading:Icon(x.$1),title:Text(x.$2),trailing:const Icon(Icons.chevron_right)),ListTile(leading:const Icon(Icons.brightness_6_outlined),title:const Text('Appearance'),trailing:DropdownButton<ThemeMode>(value:ref.watch(themeModeProvider),items:ThemeMode.values.map((v)=>DropdownMenuItem(value:v,child:Text(v.name))).toList(),onChanged:(v){if(v!=null)ref.read(themeModeProvider.notifier).select(v);})),ListTile(leading:const Icon(Icons.logout),title:const Text('Logout'),onTap:()async{await ref.read(authRepositoryProvider).logout();if(context.mounted)context.go('/login');})]));}
